16	+
17	+  </style><defs/><rect x="0" y="0" width="100%" height="100%" fill="transparent"/><g transform="matrix(1 0 0 1 1643 1651.95)" id="COLORZONE-5" fill="#FFC900" style="fill: rgb(255, 201, 0);"><rect style="stroke: rgb(0, 0, 0); stroke-width: 2; stroke-dasharray: none; stroke-linecap: round; stroke-dashoffset: 0; stroke-linejoin: round; stroke-miterlimit: 10; fill: rgb(255, 201, 0); fill-rule: nonzero; opacity: 1;" x="-481.9" y="-141.75" rx="0" ry="0" width="963.8" height="283.5" fill="#FFC900"/></g></svg>`);
18	+    expect(loaded.objects).toHaveLength(2);
19	+  });
20	+
21	+  test('can load svgs with style tags with nested at-rules', async () => {
22	+    const loaded = await loadSVGFromString(`
23	+      <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 20 20">
